.spec-card-wrapper {
  border: 1px solid #e5e5e5; border-radius: 8px; background: #ffffff; margin: 24px 0;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  box-shadow: 0 2px 8px rgba(0,0,0,0.04); overflow: hidden; box-sizing: border-box;
}
.spec-card-wrapper * { box-sizing: border-box; }
.spec-main-body { display: table; width: 100%; table-layout: fixed; }

/* 布局 */
.spec-panel-left { display: table-cell; width: 30%; background: #fafafa; border-right: 1px solid #eee; vertical-align: top; padding: 24px 16px; text-align: center; }
.spec-panel-right { display: table-cell; width: 70%; padding: 4px 24px 24px 24px; vertical-align: top; }

/* 图片与标题 */
.spec-img-box { width: 100%; min-height: 160px; margin-bottom: 16px; display: flex; align-items: center; justify-content: center; }
.spec-img-box img { max-width: 100%; max-height: 160px; object-fit: contain; border-radius: 4px; transition: opacity 0.2s ease; }
.spec-main-title { margin: 0 0 12px 0; font-size: 16px; color: #111; font-weight: 600; }

/* 标签 */
.spec-tags-container { display: flex; flex-wrap: wrap; gap: 6px; justify-content: center; }
.spec-tag { background: #f3f3f3; color: #555; padding: 2px 6px; font-size: 11px; border-radius: 4px; border: 1px solid #e8e8e8; }

/* 右侧新增：颜色卡片列表布局 */
.spec-color-row-layout { display: flex; flex-wrap: wrap; gap: 12px; padding: 10px 0; }
.spec-color-item { 
  display: flex; align-items: center; gap: 8px; padding: 6px 12px; 
  border: 1px solid #e0e0e0; border-radius: 6px; cursor: pointer; 
  transition: all 0.2s ease; background: #fff;
}
.spec-color-item:hover { border-color: #999; }
.spec-color-item.active { border-color: #111; background: #f9f9f9; font-weight: bold; }
.spec-color-lens { width: 14px; height: 14px; border-radius: 50%; border: 1px solid rgba(0,0,0,0.15); display: inline-block; }
.spec-color-text { font-size: 12px; color: #333; }

/* 参数表格 */
.spec-group-title { font-weight: bold; font-size: 13px; color: #222; border-bottom: 2px solid #333; padding: 16px 0 6px 0; margin-top: 8px; }
.spec-row { display: flex; justify-content: space-between; align-items: flex-start; padding: 8px 0; border-bottom: 1px dashed #efefef; gap: 12px; }
.spec-key { color: #666; font-size: 12px; min-width: 90px; flex-shrink: 0; text-align: left; }
.spec-val { color: #222; font-size: 12px; text-align: right; word-break: break-word; }

/* 📱 手机端适配 */
@media (max-width: 767px) {
  .spec-main-body { display: block; }
  .spec-panel-left { display: block; width: 100%; border-right: none; border-bottom: 1px solid #eee; padding: 20px 16px; }
  .spec-panel-right { display: block; width: 100%; padding: 16px 16px; }
  .spec-row { flex-direction: column; gap: 4px; }
  .spec-key { min-width: 100%; color: #888; font-size: 11px; }
  .spec-val { text-align: left; padding-left: 2px; }
  .spec-color-row-layout { gap: 8px; }
  .spec-color-item { flex: 1 1 calc(50% - 4px); justify-content: center; } /* 手机上两两平分 */
}







