function switchSpecColor(element, imgPath) {
  // 1. 切换右侧颜色选项卡片的激活状态
  const container = element.parentElement;
  container.querySelectorAll('.spec-color-item').forEach(el => el.classList.remove('active'));
  element.classList.add('active');

  // 2. 联动改变左侧固定位置的缩略图
  const card = element.closest('.spec-card-wrapper');
  const img = card.querySelector('.spec-target-img');
  img.style.opacity = 0;
  setTimeout(() => {
    img.src = imgPath;
    img.style.opacity = 1;
  }, 150);
}
